('lib/content/pa_scolarite/sanction_pages/causes_aggravation_sanction/victime_chargee_mission_page.dart','f00038','3 : CHAMP D''APPLICATION',38,'TextSpan','➤ LES DESTRUCTIONS, DÉGRADATIONS ET DÉTÉRIORATIONS (ARTICLE ','➤ LES DESTRUCTIONS, DÉGRADATIONS ET DÉTÉRIORATIONS (ARTICLE ','{}'::jsonb,true),
