('lib/content/pa_scolarite/sanction_pages/causes_aggravation_sanction/victime_chargee_mission_page.dart','f00040','3 : CHAMP D''APPLICATION',40,'TextSpan','Les violences volontaires avec ITT ≤ et > à 8 jours à l''encontre des élus locaux sont érigées en infraction autonome (art. ','Les violences volontaires avec ITT ≤ et > à 8 jours à l''encontre des élus locaux sont érigées en infraction autonome (art. ','{}'::jsonb,true),
